<script lang="ts">
 import {onMount} from 'svelte';
 import type {CommunityGateway,ModerationReport} from '../application/community';
 import {categoryNames,validReport} from '../domain/content';
 let {gateway}:{gateway:CommunityGateway}=$props();
 let account=$state<string|null>(null),reports=$state<ModerationReport[]>([]),reasons=$state<Record<string,string>>({}),busy=$state(false),message=$state(''),more=$state(false);
 async function load(after=''){busy=true;try{account=await gateway.account();if(!account){message='Алдымен кіріңіз';return;}const result=await gateway.reports(account,after);reports=after?[...reports,...result.items]:result.items;more=result.hasMore;}catch(failure){message=failure instanceof Error?failure.message:'Шағымдар жүктелмеді';}finally{busy=false;}}
 onMount(()=>{void load();});
 async function decide(item:ModerationReport,status:string){if(!account||!validReport(reasons[item.id]||'')){message='Шешім себебін 8–2000 таңбамен жазыңыз';return;}busy=true;try{await gateway.resolve(account,item.id,status,reasons[item.id]);reports=reports.filter(report=>report.id!==item.id);message='Шешім сақталды';}catch(failure){message=failure instanceof Error?failure.message:'Шешім сақталмады';}finally{busy=false;}}
 async function visibility(item:ModerationReport,hidden:boolean){if(!account||!validReport(reasons[item.id]||'')){message='Әрекет себебін жазыңыз';return;}busy=true;try{await gateway.visibility(account,item.targetId,hidden,reasons[item.id]);message=hidden?'Пікір жасырылды':'Пікір қайта ашылды';}catch(failure){message=failure instanceof Error?failure.message:'Әрекет орындалмады';}finally{busy=false;}}
</script>
<svelte:head><title>Шағымдар — Qmanga</title><meta name="robots" content="noindex"/></svelte:head>
<a class="auth-link" href="/moderation">Жарияланымдарды тексеру</a><h1>Шағымдар</h1>{#if message}<p class="form-message" role="status">{message}</p>{/if}
{#each reports as item}<article><h2>{categoryNames[item.category]||item.category}</h2><p>{item.reason}</p><dl><dt>Нысан</dt><dd>{item.targetType} · {item.targetId}</dd>{#if item.pageId}<dt>Бет</dt><dd>{item.pageId}</dd>{/if}</dl>{#if item.releaseId}<a class="auth-link" href={`/read/${item.releaseId}`}>Тарауды қарау</a>{/if}<label>Модератор шешімінің себебі<textarea bind:value={reasons[item.id]} minlength="8" maxlength="2000" rows="3"></textarea></label><div class="actions">{#if item.targetType==='comment'}<button class="button subtle" disabled={busy} onclick={()=>visibility(item,true)}>Пікірді жасыру</button><button class="button subtle" disabled={busy} onclick={()=>visibility(item,false)}>Қайта ашу</button>{/if}<button class="button primary" disabled={busy} onclick={()=>decide(item,'resolved')}>Шешілді</button><button class="button subtle" disabled={busy} onclick={()=>decide(item,'dismissed')}>Негізсіз</button></div></article>{:else}{#if !busy}<p class="empty-state">Қаралмаған шағым жоқ.</p>{/if}{/each}{#if more}<button class="button" disabled={busy} onclick={()=>load(reports[reports.length-1].id)}>Тағы жүктеу</button>{/if}{#if busy}<p role="status">Жүктелуде…</p>{/if}
<style>h1{font-size:26px}h2{font-size:20px}article{padding:24px 0;border-bottom:1px solid var(--line)}article p{white-space:pre-wrap;overflow-wrap:anywhere;margin:12px 0}dl{font-size:13px}dd{margin:0;overflow-wrap:anywhere}label{display:grid;gap:8px;font-size:14px}.actions{display:flex;flex-wrap:wrap;gap:10px;margin-top:12px}</style>
